//! Parity test verifying exact byte-level parity and error behavior between
//! C# PartgeoPatcher and Rust PartgeoPatcher.
//! Fixture generated by tests/oracle_partgeo (PartgeoOracle.csproj).

use against_rome_modifier::{PartgeoOptions, PartgeoPatcher};
use serde_json::Value;
use sha2::{Digest, Sha256};

fn b64_decode(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let chars: Vec<char> = s.chars().filter(|c| !c.is_whitespace()).collect();
    let b64_table = |c: char| -> Option<u8> {
        match c {
            'A'..='Z' => Some(c as u8 - b'A'),
            'a'..='z' => Some(c as u8 - b'a' + 26),
            '0'..='9' => Some(c as u8 - b'0' + 52),
            '+' => Some(62),
            '/' => Some(63),
            '=' => None,
            _ => None,
        }
    };

    let mut i = 0;
    while i < chars.len() {
        let chunk = &chars[i..std::cmp::min(i + 4, chars.len())];
        if chunk.len() < 4 {
            break;
        }
        let b0 = b64_table(chunk[0]).unwrap_or(0);
        let b1 = b64_table(chunk[1]).unwrap_or(0);
        let b2 = b64_table(chunk[2]);
        let b3 = b64_table(chunk[3]);

        out.push((b0 << 2) | (b1 >> 4));
        if let Some(v2) = b2 {
            out.push(((b1 & 0x0F) << 4) | (v2 >> 2));
            if let Some(v3) = b3 {
                out.push(((v2 & 0x03) << 6) | v3);
            }
        }
        i += 4;
    }
    out
}

#[test]
fn partgeo_csharp_parity_matches_oracle_fixture() {
    let fixture: Value =
        serde_json::from_str(include_str!("fixtures/csharp-partgeo.json")).unwrap();

    // 1. Verify freshness of C# oracle sources
    for (name, source) in [
        (
            "PartgeoPatcher",
            include_bytes!("../../../src.Core/Core/Patches/PartgeoPatcher.cs").as_slice(),
        ),
        (
            "PatchText",
            include_bytes!("../../../src.Core/Core/Patches/PatchText.cs").as_slice(),
        ),
        (
            "GameLZSS",
            include_bytes!("../../../src.Shared/Core/GameLZSS.cs").as_slice(),
        ),
    ] {
        assert_eq!(
            fixture["Sources"][name].as_str().unwrap(),
            format!("{:X}", Sha256::digest(source)),
            "Regenerate stale C# oracle fixture: {name}"
        );
    }

    let cases = fixture["Cases"].as_array().unwrap();
    assert!(
        cases.len() >= 30,
        "Oracle fixture unexpectedly small: {}",
        cases.len()
    );

    let mut mismatches = Vec::new();
    let mut passed_count = 0;

    for case in cases {
        let name = case["Name"].as_str().unwrap();
        let arc_height = case["ProjectileArcHeight"].as_bool().unwrap();
        let is_success = case["IsSuccess"].as_bool().unwrap();
        let input_b64 = case["InputBase64"].as_str().unwrap();
        let input = b64_decode(input_b64);

        let options = PartgeoOptions {
            projectile_arc_height: arc_height,
        };

        let rust_result = PartgeoPatcher::get_patched_bytes(&input, &options);

        match (is_success, rust_result) {
            (true, Ok(rust_output)) => {
                let csharp_output = b64_decode(case["OutputBase64"].as_str().unwrap());
                if rust_output != csharp_output {
                    mismatches.push(format!(
                        "[{name}] Output byte mismatch: C# len={}, Rust len={}",
                        csharp_output.len(),
                        rust_output.len()
                    ));
                } else {
                    passed_count += 1;
                }
            }
            (false, Err(_rust_err)) => {
                passed_count += 1;
            }
            (true, Err(rust_err)) => {
                mismatches.push(format!(
                    "[{name}] Expected success from C#, but Rust failed with error: {rust_err}"
                ));
            }
            (false, Ok(rust_output)) => {
                mismatches.push(format!(
                    "[{name}] Expected error from C# ({:?}), but Rust succeeded with {} bytes",
                    case["ErrorType"].as_str(),
                    rust_output.len()
                ));
            }
        }
    }

    assert!(
        mismatches.is_empty(),
        "{} mismatches out of {} cases:\n{}",
        mismatches.len(),
        cases.len(),
        mismatches.join("\n")
    );

    assert_eq!(passed_count, cases.len());
}
